"""Python/PyStan 3.10.0 conversion of gp_rstan.R.

Fits the ARD squared-exponential GP regression model with a linear mean
function, using the equivalent Stan program and sampler configuration as the
original R/RStan script.
"""

import json

import numpy as np
import stan

STAN_CODE = """
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X); // == cols(X_new)
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

transformed parameters {
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                   + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);
}

model {
  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd   = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
"""


def read_csv_matrix(path, dtype=float):
    """Read a headerless-index CSV (first row is a header) as a 2-D array."""
    arr = np.loadtxt(path, delimiter=",", skiprows=1, dtype=dtype)
    return np.atleast_2d(arr)


def main():
    meta = json.load(open("meta_public.json"))
    train_X = read_csv_matrix("train_X.csv")
    test_X = read_csv_matrix("test_X.csv")
    train_y = np.loadtxt("train_y.csv", delimiter=",", skiprows=1, dtype=float).ravel()

    P = int(meta["P"])
    jitter = float(meta["jitter"])

    N, D = train_X.shape
    N_new = test_X.shape[0]

    H = np.column_stack([np.ones(N), train_X[:, 0], train_X[:, 1]])
    if N_new > 0:
        H_new = np.column_stack([np.ones(N_new), test_X[:, 0], test_X[:, 1]])
    else:
        H_new = np.zeros((0, P))

    data = {
        "N": N,
        "D": D,
        "X": train_X,
        "P": P,
        "H": H,
        "y": train_y,
        "jitter": jitter,
        "N_new": N_new,
        "X_new": test_X if N_new > 0 else np.zeros((0, D)),
        "H_new": H_new,
    }

    posterior = stan.build(STAN_CODE, data=data, random_seed=1)
    fit = posterior.sample(
        num_chains=4,
        num_warmup=1000,
        num_samples=1000,
        num_thin=2,
        save_warmup=False,
        refresh=200,
        init_radius=0.1,
        delta=0.93,
        max_depth=14,
        gamma=0.05,
        kappa=0.75,
        t0=10,
        init_buffer=100,
        term_buffer=50,
        window=25,
    )

    alpha_post = float(np.mean(fit["alpha"]))
    sigma_post = float(np.mean(fit["sigma"]))
    rho_post = np.mean(fit["rho"], axis=1)
    beta_post = np.mean(fit["beta"], axis=1)

    np.savetxt("alpha_est.csv", np.array([alpha_post]))
    np.savetxt("sigma_est.csv", np.array([sigma_post]))
    np.savetxt("rho_est.csv", rho_post)
    np.savetxt("beta_est.csv", beta_post)

    print("Posterior means:")
    print("alpha:", alpha_post)
    print("sigma:", sigma_post)
    print("rho:  ", " ".join(f"{v:.6f}" for v in rho_post))
    print("beta: ", " ".join(f"{v:.6f}" for v in beta_post))


if __name__ == "__main__":
    main()

